import { test, expect, Page } from '@playwright/test';

test.describe('Phone Number Field - Numeric Input Validation', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('data:text/html,<html><body><form><label for="phone">Phone Number</label><input type="tel" id="phone" name="phone" placeholder="Enter phone number" /></form></body></html>');
  });

  test('should accept numeric input in phone number field', async () => {
    const phoneInput = page.getByLabel('Phone Number');

    await phoneInput.fill('1234567890');

    const value = await phoneInput.inputValue();
    expect(value).toBe('1234567890');
  });

  test('should reject non-numeric characters in phone number field', async () => {
    const phoneInput = page.getByLabel('Phone Number');

    // Attempt to enter text with special characters and letters
    await phoneInput.fill('123abc@#$456');

    const value = await phoneInput.inputValue();
    // The input should only contain numeric characters
    expect(value).toMatch(/^\d*$/);
  });

  test('should accept phone number with formatting characters', async () => {
    const phoneInput = page.getByLabel('Phone Number');

    // Enter a formatted phone number
    await phoneInput.fill('(123) 456-7890');

    const value = await phoneInput.inputValue();
    // Should preserve the input as entered
    expect(value).toBe('(123) 456-7890');
  });

  test('should handle paste events with non-numeric content', async () => {
    const phoneInput = page.getByLabel('Phone Number');

    // Set initial value
    await phoneInput.fill('');

    // Simulate paste event with mixed content
    await page.evaluate(() => {
      const input = document.getElementById('phone') as HTMLInputElement;
      const pasteEvent = new ClipboardEvent('paste', {
        clipboardData: new DataTransfer(),
        bubbles: true,
      });
      pasteEvent.clipboardData?.setData('text/plain', 'abc123def456');
      input.dispatchEvent(pasteEvent);
    });

    // Verify the field exists and is accessible
    await expect(phoneInput).toBeVisible();
  });

  test('should allow clearing the phone number field', async () => {
    const phoneInput = page.getByLabel('Phone Number');

    await phoneInput.fill('9876543210');
    expect(await phoneInput.inputValue()).toBe('9876543210');

    await phoneInput.clear();
    expect(await phoneInput.inputValue()).toBe('');
  });

  test('should validate phone number length constraints', async () => {
    const phoneInput = page.getByLabel('Phone Number');

    // Test with standard 10-digit phone number
    await phoneInput.fill('5551234567');
    let value = await phoneInput.inputValue();
    expect(value).toHaveLength(10);

    // Test with longer number
    await phoneInput.fill('15551234567');
    value = await phoneInput.inputValue();
    expect(value).toHaveLength(11);
  });

  test('should reject special characters while accepting numbers', async () => {
    const phoneInput = page.getByLabel('Phone Number');

    const testCases = [
      { input: '123-456-7890', shouldContainNumbers: true },
      { input: '!@#$%^&*()', shouldContainNumbers: false },
      { input: '555.123.4567', shouldContainNumbers: true },
      { input: '1234567890', shouldContainNumbers: true },
    ];

    for (const testCase of testCases) {
      await phoneInput.fill(testCase.input);
      const value = await phoneInput.inputValue();

      if (testCase.shouldContainNumbers) {
        expect(value).toMatch(/\d/);
      }
    }
  });

  test('should maintain focus on phone number field during input', async () => {
    const phoneInput = page.getByLabel('Phone Number');

    await phoneInput.focus();
    expect(await phoneInput.evaluate(el => el === document.activeElement)).toBe(true);

    await phoneInput.type('1234567890');
    expect(await phoneInput.evaluate(el => el === document.activeElement)).toBe(true);
  });
});
